/** Scene media changes presentation metadata only, never quest flags or rewards. */
export function arrivalShot(shots,scene,state){if(!scene?.chapter||scene.chapter>8||scene.interior||scene.chapter===1&&scene.key!=='security')return null;const shot=shots.find(s=>s.kind==='arrival'&&s.chapter===scene.chapter);return shot&&!(state.cinemaSeen||[]).includes(shot.id)?shot:null;}
export function encounterShot(shots,enemies,state){const known=new Set(state.cinemaEncounters||[]);const e=enemies.find(e=>e.species&&!known.has(e.species.replace(/-elder$/,'')));if(!e)return null;const id=e.species.replace(/-elder$/,''),shot=shots.find(s=>s.kind==='creature'&&s.species===id);return shot?{...shot,title:e.name,subtitle:e.move+' · '+(e.moveShape==='line'?'Step sideways from the marked line.':'Move outside the marked circle.')}:null;}
export function rememberEncounter(state,enemies){state.cinemaEncounters=[...new Set([...(state.cinemaEncounters||[]),...enemies.filter(e=>e.species).map(e=>e.species.replace(/-elder$/,''))])];}
export function albumShots(shots,state){return shots.filter(s=>(state.cinemaSeen||[]).includes(s.id)||s.kind==='arrival'&&s.chapter<state.chapter||s.kind==='creature'&&(state.cinemaEncounters||[]).includes(s.species));}
export class JourneyCinema{
 constructor({onOpen=()=>{},onClose=()=>{}}={}){this.onOpen=onOpen;this.onClose=onClose;this.active=false;this.enabled=localStorage.getItem('ash-cinematic-arrivals')!=='off';this.generation=0;this.shots=[];this.ready=fetch(new URL('../cinema/journey-manifest.json',import.meta.url)).then(r=>r.ok?r.json():{shots:[]}).then(m=>this.shots=m.shots||[]).catch(()=>[]);
 const room=document.createElement('dialog');room.id='journey-cinema';room.setAttribute('aria-labelledby','journey-title');room.innerHTML='<div class="journey-top"><div><small id="journey-kind"></small><h2 id="journey-title"></h2></div><button id="journey-skip">Return to game</button></div><video id="journey-video" controls playsinline muted preload="none"></video><p id="journey-caption"></p><button id="journey-play">Play scene</button>';document.querySelector('#game').append(room);this.room=room;this.video=room.querySelector('video');room.querySelector('#journey-skip').onclick=()=>this.close(true);room.querySelector('#journey-play').onclick=()=>this.video.play().catch(()=>{});room.addEventListener('cancel',e=>{e.preventDefault();this.close(true);});this.video.onended=()=>this.close(true);this.video.onerror=()=>{this.room.dataset.mediaError=this.video.error?.message||'Media unavailable';this.close(false);};this.video.onloadeddata=()=>clearTimeout(this.timeout);
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&this.active)this.video.pause();});
 }
 async arrival(scene,state){const generation=this.generation;await this.ready;if(generation!==this.generation||!this.enabled||this.active||scene.location!==undefined&&state.scene!==scene.location)return;const shot=arrivalShot(this.shots,scene,state);if(shot)this.play(shot,state);}
 async encounter(enemies,state){const generation=this.generation;await this.ready;if(generation!==this.generation||state.mode&&state.mode!=='battle')return;const shot=encounterShot(this.shots,enemies,state);rememberEncounter(state,enemies);if(this.enabled&&!this.active&&shot)this.play(shot,state);}
 play(shot,state,{replay=false}={}){if(this.active)this.close(false);this.state=state;this.shot=shot;this.replay=replay;this.active=true;this.invoker=document.activeElement;this.room.querySelector('#journey-title').textContent=shot.title;this.room.querySelector('#journey-kind').textContent=shot.kind==='creature'?'FIRST CONTACT':'THE JOURNEY';this.room.querySelector('#journey-caption').textContent=shot.subtitle||'';this.onOpen();this.room.showModal();this.video.src=new URL(shot.src,new URL('../',import.meta.url)).href;this.video.muted=true;this.video.load();this.video.play().catch(()=>{});this.room.querySelector('#journey-skip').focus();this.timeout=setTimeout(()=>{if(this.video.readyState<2)this.close(false);},15000);}
 close(remember=false){if(!this.active)return;clearTimeout(this.timeout);if(remember&&!this.replay){this.state.cinemaSeen=[...new Set([...(this.state.cinemaSeen||[]),this.shot.id])];}this.video.pause();this.video.removeAttribute('src');this.video.load();this.room.close();this.active=false;if(!this.cancelling){this.onClose();this.invoker?.focus();}}
 cancel(){this.generation++;this.cancelling=true;this.close(false);this.cancelling=false;}
 setEnabled(enabled){this.enabled=enabled;localStorage.setItem('ash-cinematic-arrivals',enabled?'on':'off');}
}
